insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('4c8eafe1-e001-4c2a-b746-b19e809ad119', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Differentiating for Language Proficiency Levels', 'This section prepares teachers to plan one rigorous lesson with multiple entry points. Students learn to differentiate language demand while preserving access to meaningful content.', 5),
