  ('58ca1791-f781-4f66-a5c8-9b0625b70620', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '108fef1f-4f52-4953-9c1c-19058145b800', 'concept'::public.curated_course_node_type, 'adapted texts', null, 0),
