  ('70f6e4de-eabf-4969-b85e-9a80444d6d07', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '2de29460-d41a-4cdf-8a21-4552bbddecc1', 'concept'::public.curated_course_node_type, 'heterogeneous grouping', null, 0),
