  ('f3143a77-4308-4871-bc08-3096202d1565', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '2de29460-d41a-4cdf-8a21-4552bbddecc1', 'concept'::public.curated_course_node_type, 'peer models', null, 2),
  ('28f43d99-4e30-4e9c-b5a1-559759d618bc', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '2de29460-d41a-4cdf-8a21-4552bbddecc1', 'concept'::public.curated_course_node_type, 'role-based collaboration', null, 3),
  ('04cb907c-47af-4772-b65f-e83c2e0d6e2c', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Assessing ELL Students', 'This section centers fairness: assessment should reveal what multilingual learners know and can do, not merely how well they navigate unnecessary language barriers.', 6),
