  ('201bc68b-2727-4b1a-bbd0-ddf4ad7790a4', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '8a40d6b3-8388-4732-b40c-b868163288a4', 'concept'::public.curated_course_node_type, 'construct-relevant language', null, 0),
