  ('b29874ec-e01c-4b4c-a73f-7f03dd7e0cd5', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '04cb907c-47af-4772-b65f-e83c2e0d6e2c', 'subtopic'::public.curated_course_node_type, 'Formative Assessment', 'The point is to use frequent evidence to adjust instruction before high-stakes judgments.', 1),
  ('a68b9f2c-098e-49c5-95cb-eb587f2b9455', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', 'b29874ec-e01c-4b4c-a73f-7f03dd7e0cd5', 'concept'::public.curated_course_node_type, 'exit tickets', null, 0),
