  ('d5c567d0-639b-40b2-ab9c-47df96caf02f', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '46365d5f-e1a2-4310-9064-43b87f713ad3', 'concept'::public.curated_course_node_type, 'translation and interpretation', null, 0),
