  ('3197f48a-633f-4703-a66c-73b73168f588', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Family and Community Engagement', 'This section treats families and communities as partners with linguistic, cultural, and experiential knowledge. Students learn communication practices that create trust and shared educational purpose.', 7),
