  ('41fd307b-f4a0-42f1-b5be-1b58667ddef5', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', '3197f48a-633f-4703-a66c-73b73168f588', 'subtopic'::public.curated_course_node_type, 'Funds of Knowledge', 'The gist is to draw on family and community expertise as curriculum and relationship assets.', 1),
