  ('26bb567b-3c50-4e2b-b74f-70af70df61f8', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Translanguaging and Bilingual Pedagogies', 'This section frames students'' full linguistic repertoires as resources for sensemaking, identity, and academic learning. Teachers learn how bilingual practices can support both content learning and English development.', 9),
