  ('6652625b-e418-44d4-8ea3-b6331eb34e48', 'e7f8a9b0-1c2d-4e84-9f34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Literacy for Multilingual Learners', 'This added section integrates TESOL methods with literacy development. Students learn how oral language, vocabulary, phonology, morphology, background knowledge, and reading comprehension interact for multilingual learners.', 11),
