  'Teaching English Language Learners / TESOL Methods',
  'This course prepares MEd students to design, teach, assess, and reflect on instruction for English language learners and multilingual students. Students study second language acquisition, WIDA standards, SIOP, sheltered instruction, translanguaging, academic language, multilingual literacy, culturally sustaining pedagogy, assessment equity, family engagement, and program/legal contexts. The course emphasizes asset-based instruction that integrates language development with meaningful content learning.',
  $tesljson${"slug": "teaching-english-language-learners-tesol-methods", "title": "Teaching English Language Learners / TESOL Methods", "description": "This course prepares MEd students to design, teach, assess, and reflect on instruction for English language learners and multilingual students. Students study second language acquisition, WIDA standards, SIOP, sheltered instruction, translanguaging, academic language, multilingual literacy, culturally sustaining pedagogy, assessment equity, family engagement, and program/legal contexts. The course emphasizes asset-based instruction that integrates language development with meaningful content learning.", "topics": [{"id": "46699b2d-3c55-4cad-b6c4-13fd99ea2774", "type": "topic", "title": "Second Language Acquisition Theory", "description": "This opening section gives teachers a research-grounded understanding of how additional languages develop. Students learn to connect theory to classroom decisions rather than treating language learning as either simple exposure or vocabulary memorization.", "children": [{"id": "78dbedc0-f283-4eff-9a76-2c0b4e3e87c9", "type": "subtopic", "title": "Core SLA Concepts", "children": [{"id": "74338f77-a04b-4f15-901a-b4af9c0f9fca", "type": "concept", "title": "input, interaction, and output"}, {"id": "4e759de5-3d31-4299-a729-4444b08fb365", "type": "concept", "title": "interlanguage"}, {"id": "7b8b5ef7-34ae-48b8-b00c-a94e936414d1", "type": "concept", "title": "noticing and feedback"}, {"id": "9045131f-e06c-4115-afb1-4f8287122440", "type": "concept", "title": "affective filter and motivation"}], "description": "Students learn the vocabulary needed to explain language learning in practical, teacher-facing terms."}, {"id": "ba4ec033-a15a-48a2-b84a-c7bfb1ea5b3b", "type": "subtopic", "title": "Social and Identity Dimensions", "children": [{"id": "3153a608-6d18-4a4e-9f19-4934ab37182c", "type": "concept", "title": "identity and investment"}, {"id": "1574092a-1534-4097-992e-054dc6e15d8c", "type": "concept", "title": "peer interaction"}, {"id": "c254c25d-4166-46bd-b498-a8af98b2f923", "type": "concept", "title": "language ideologies"}, {"id": "7e314e8f-312b-4993-a59e-e4e453ef33b6", "type": "concept", "title": "classroom belonging"}], "description": "The point is to see language learning as social participation, not only individual cognition."}, {"id": "e11d1b67-6e5b-4ea0-b4e2-45709adc194c", "type": "subtopic", "title": "Instructional Implications", "children": [{"id": "a2156e0b-90a0-4d43-be87-02d564f08ff1", "type": "concept", "title": "language-rich routines"}, {"id": "fa1ae2c1-d721-4f47-85a9-bf8a29d55644", "type": "concept", "title": "wait time and rehearsal"}, {"id": "f6c7970b-d326-43a7-8220-f0c4df159c00", "type": "concept", "title": "feedback for meaning and form"}, {"id": "3757610b-7223-42a1-a442-046ab610d30c", "type": "concept", "title": "scaffolded production"}], "description": "Teachers connect SLA theory to comprehensible input, structured interaction, and meaningful language use."}]}, {"id": "25427192-7070-44b4-97f0-4af227c1a555", "type": "topic", "title": "Stages of Language Development", "description": "This section helps teachers recognize developmental patterns without stereotyping learners or lowering expectations. Students learn how proficiency changes across listening, speaking, reading, and writing.", "children": [{"id": "80615705-b157-4aa4-9247-2a4e6534cd15", "type": "subtopic", "title": "Language Domains", "children": [{"id": "0bca710a-f9e8-445f-9701-72c6fbfda5cb", "type": "concept", "title": "listening"}, {"id": "dc122ed4-9973-44a2-92fc-50eb51f03266", "type": "concept", "title": "speaking"}, {"id": "2ab4d71a-370b-4802-9c62-b8822ef1f479", "type": "concept", "title": "reading"}, {"id": "c46238d2-2808-42b2-9816-b4cd4ba6f0af", "type": "concept", "title": "writing"}], "description": "Students learn to distinguish receptive and productive language growth across classroom tasks."}, {"id": "c23b7e80-5b79-4428-b3f9-7b82427cb8cd", "type": "subtopic", "title": "Developmental Progressions", "children": [{"id": "68cc60fe-1157-43a8-a936-c51eca84c751", "type": "concept", "title": "preproduction and early production"}, {"id": "fe7e510e-3ba4-4749-828a-16b1bdb07e75", "type": "concept", "title": "speech emergence"}, {"id": "d5bebc09-f6dd-4913-a54b-bef8e01bf36c", "type": "concept", "title": "intermediate fluency"}, {"id": "1ee0367f-ad54-498c-987e-9d02e9477717", "type": "concept", "title": "advanced academic language"}], "description": "The gist is to understand common movement from emerging communication toward academic precision."}, {"id": "f93de55d-2497-4d42-adfa-bd7ecbc25809", "type": "subtopic", "title": "Learner Variability", "children": [{"id": "f56604d2-1ad3-4b8a-95e8-d0066e9397be", "type": "concept", "title": "age and prior schooling"}, {"id": "324d5cae-0440-400c-bbcb-8b3433fe8615", "type": "concept", "title": "first-language literacy"}, {"id": "a18dcc19-677a-402f-98b0-22d0c1522bee", "type": "concept", "title": "interrupted formal education"}, {"id": "6f84363c-8039-4bcf-a888-67cd5920450e", "type": "concept", "title": "trauma and migration experiences"}], "description": "Teachers examine why students with the same label may need different supports."}]}, {"id": "0f73c67e-79cb-48b6-bc90-c8b750a47c8f", "type": "topic", "title": "SIOP: Sheltered Instruction Observation Protocol", "description": "This section introduces SIOP as a comprehensive planning and observation model for making grade-level content comprehensible while developing academic language.", "children": [{"id": "fda6f9dc-71b8-43f1-bfae-bb10690f2ead", "type": "subtopic", "title": "SIOP Lesson Components", "children": [{"id": "df05060b-a476-4406-8815-60b156051f88", "type": "concept", "title": "lesson preparation"}, {"id": "481cbf55-0e2d-4cc1-aea4-3e49ffdf35f8", "type": "concept", "title": "building background"}, {"id": "00cf515e-284d-43a4-ba3d-e5cd403f1b61", "type": "concept", "title": "comprehensible input"}, {"id": "d3c02b68-fba2-4530-ab09-db18722df382", "type": "concept", "title": "strategies, interaction, practice, and review"}], "description": "Students learn the major parts of the model and how they support content and language learning together."}, {"id": "9c616676-9ad9-4d2c-8594-60486337b1dd", "type": "subtopic", "title": "Content and Language Objectives", "children": [{"id": "62a31e1e-dca7-4d6a-be18-5ffd81cdea3d", "type": "concept", "title": "measurable language objectives"}, {"id": "e0363063-0482-4419-8878-b7de9f3bc8a8", "type": "concept", "title": "content-standard alignment"}, {"id": "114a9a01-eaf8-4c94-9cab-975537c645c2", "type": "concept", "title": "student-friendly wording"}, {"id": "577d300b-a9f0-4173-9c21-017f223a9ea3", "type": "concept", "title": "objective review and assessment"}], "description": "The point is to plan what students learn and the language they need to learn it."}, {"id": "aab211a7-4300-4d98-93f0-081751f518eb", "type": "subtopic", "title": "Using SIOP for Reflection", "children": [{"id": "86b2d862-aea3-4968-b087-566ae588df04", "type": "concept", "title": "lesson observation"}, {"id": "080dde9f-430d-4e58-b2b8-ee81a0557487", "type": "concept", "title": "evidence collection"}, {"id": "aa7a0c71-b0e6-4309-a431-adfbe90b48ad", "type": "concept", "title": "self-assessment"}, {"id": "908b1677-d8ac-4a8d-be26-838f54b69f74", "type": "concept", "title": "collaborative debriefing"}], "description": "Teachers learn to use the protocol as a coaching and improvement tool."}]}, {"id": "3de66cb3-03ab-47e9-a731-fb66c84a412b", "type": "topic", "title": "Sheltered Instruction Strategies", "description": "This section turns language-support principles into daily teaching moves. Students learn to make complex content accessible without diluting intellectual demand.", "children": [{"id": "12d816c1-d2d3-4eda-a12f-6113f39d4fd5", "type": "subtopic", "title": "Comprehensible Input", "children": [{"id": "28ce5bd3-f4ed-4af4-b1db-03c097e7632b", "type": "concept", "title": "visuals and realia"}, {"id": "cab53088-3932-4bcf-ad67-db359874ba7d", "type": "concept", "title": "modeling and gestures"}, {"id": "aa459bef-a8d4-42cc-990a-5ff0016869f3", "type": "concept", "title": "chunking and paraphrasing"}, {"id": "b15fcaf3-df3e-418b-9662-7614c9692d15", "type": "concept", "title": "checking comprehension"}], "description": "Students learn how to adjust language, visuals, pacing, and examples so learners can access meaning."}, {"id": "f3534240-cbe2-48fb-979b-aacf392d140a", "type": "subtopic", "title": "Scaffolding Academic Tasks", "children": [{"id": "8b516b15-e98b-41b4-b35d-227b1fb91427", "type": "concept", "title": "sentence frames"}, {"id": "c9b552ba-81d9-4025-955f-edc456c6e569", "type": "concept", "title": "graphic organizers"}, {"id": "391aec58-dfeb-4045-b4da-64b610622cf8", "type": "concept", "title": "word banks"}, {"id": "0f9b2d9b-13ac-40c5-873a-fa9f8b4b6334", "type": "concept", "title": "guided practice and gradual release"}], "description": "The gist is to support learners temporarily while building independence."}, {"id": "88da5520-6e94-4632-bc56-c3fb941b0479", "type": "subtopic", "title": "Interaction and Oral Language", "children": [{"id": "edd89df6-a7df-4042-b31e-772bbcd39f12", "type": "concept", "title": "partner rehearsal"}, {"id": "641d9ad4-a96b-4dd8-9935-ea45944f0e3d", "type": "concept", "title": "structured discussion roles"}, {"id": "2ea5d31c-fcb2-4c0e-9d24-619e719e7276", "type": "concept", "title": "accountable talk stems"}, {"id": "0c9f831a-6025-4def-ba3a-ea167b7f81f5", "type": "concept", "title": "collaborative problem solving"}], "description": "Teachers learn to structure purposeful talk so multilingual learners rehearse ideas and language."}]}, {"id": "f96350a5-49d5-4ef4-96bb-13908c60d1a2", "type": "topic", "title": "WIDA Standards and Proficiency Levels", "description": "This section helps educators use language-development standards as planning tools, not compliance paperwork. Students learn to connect proficiency levels with meaningful content-area language expectations.", "children": [{"id": "508609c5-1de7-4eab-ac7b-2bfb2f1e6feb", "type": "subtopic", "title": "WIDA Framework", "children": [{"id": "947d3c09-f0b8-4b4e-b75a-48b65dc2a574", "type": "concept", "title": "Key Language Uses"}, {"id": "038c45bb-44a6-45d7-bcac-c0134fb3167d", "type": "concept", "title": "language expectations"}, {"id": "a4507378-395c-4326-8927-83fc1aa6130f", "type": "concept", "title": "proficiency level descriptors"}, {"id": "416a87d9-6569-47fa-9c61-a9ab1253e18a", "type": "concept", "title": "Can Do philosophy"}], "description": "Students learn the purpose and structure of WIDA's language development standards."}, {"id": "b3900ef5-dc5a-48a0-a6e6-fc5a210e70ad", "type": "subtopic", "title": "Interpreting Proficiency Data", "children": [{"id": "b1f22a7c-0f09-4d87-ab1a-1bb18bd78a90", "type": "concept", "title": "ACCESS scores"}, {"id": "db596ec6-12df-4442-bbda-689a78a5dd8d", "type": "concept", "title": "domain profiles"}, {"id": "6852be0a-b5da-474f-8fbc-4d281dbe7eb6", "type": "concept", "title": "growth patterns"}, {"id": "25aed22f-9965-46c4-adce-14d36ee9e5b9", "type": "concept", "title": "limits of standardized proficiency data"}], "description": "The point is to use scores carefully as one source of information about support needs."}, {"id": "0ff510db-0bd3-4dad-a690-4f7bb779dba3", "type": "subtopic", "title": "Standards-Based Language Planning", "children": [{"id": "4840185f-f6ed-41b2-be9b-3ca3ba6e9bda", "type": "concept", "title": "content-language alignment"}, {"id": "ca6d672e-cbf4-45b1-9c74-a0159add5a64", "type": "concept", "title": "language functions"}, {"id": "7baf2d0c-b8ff-4016-a5c7-a837e204969c", "type": "concept", "title": "discipline-specific features"}, {"id": "347870b4-6adc-440d-9e63-8bc98a9bd289", "type": "concept", "title": "success criteria"}], "description": "Teachers connect WIDA language expectations to lessons, units, and assessment."}]}, {"id": "4c8eafe1-e001-4c2a-b746-b19e809ad119", "type": "topic", "title": "Differentiating for Language Proficiency Levels", "description": "This section prepares teachers to plan one rigorous lesson with multiple entry points. Students learn to differentiate language demand while preserving access to meaningful content.", "children": [{"id": "108fef1f-4f52-4953-9c1c-19058145b800", "type": "subtopic", "title": "Differentiated Input", "children": [{"id": "58ca1791-f781-4f66-a5c8-9b0625b70620", "type": "concept", "title": "adapted texts"}, {"id": "b9f9f3b1-37e0-4229-a954-b810a73d0128", "type": "concept", "title": "previewing vocabulary"}, {"id": "dfb7e871-9570-4df5-825b-27573c472af9", "type": "concept", "title": "multimodal supports"}, {"id": "74121a92-e887-4e0b-bc0b-dc17f180e84d", "type": "concept", "title": "native-language resources"}], "description": "Students learn to make texts, lectures, and directions more accessible for varied proficiency levels."}, {"id": "9739d4d2-b353-4db5-9f63-a2ffb903042b", "type": "subtopic", "title": "Differentiated Output", "children": [{"id": "0180f033-713d-49c2-8907-8e036a2bcf6d", "type": "concept", "title": "oral rehearsal before writing"}, {"id": "2c1dcdaf-6feb-4d9a-a25a-f6aab7f180d9", "type": "concept", "title": "choice of product"}, {"id": "0e880d32-1178-46dd-bdbc-1c6bf3097625", "type": "concept", "title": "language frames by level"}, {"id": "85e9874b-1aee-4bd6-be90-6dac327e7f6e", "type": "concept", "title": "expanded response pathways"}], "description": "The gist is to give learners appropriate ways to show thinking while stretching language."}, {"id": "2de29460-d41a-4cdf-8a21-4552bbddecc1", "type": "subtopic", "title": "Grouping and Peer Support", "children": [{"id": "70f6e4de-eabf-4969-b85e-9a80444d6d07", "type": "concept", "title": "heterogeneous grouping"}, {"id": "336a027f-a7ae-4ade-b904-d22ccba8a0b7", "type": "concept", "title": "same-language partnerships"}, {"id": "f3143a77-4308-4871-bc08-3096202d1565", "type": "concept", "title": "peer models"}, {"id": "28f43d99-4e30-4e9c-b5a1-559759d618bc", "type": "concept", "title": "role-based collaboration"}], "description": "Teachers learn to use peers strategically without isolating or overburdening multilingual learners."}]}, {"id": "04cb907c-47af-4772-b65f-e83c2e0d6e2c", "type": "topic", "title": "Assessing ELL Students", "description": "This section centers fairness: assessment should reveal what multilingual learners know and can do, not merely how well they navigate unnecessary language barriers.", "children": [{"id": "8a40d6b3-8388-4732-b40c-b868163288a4", "type": "subtopic", "title": "Language Versus Content", "children": [{"id": "201bc68b-2727-4b1a-bbd0-ddf4ad7790a4", "type": "concept", "title": "construct-relevant language"}, {"id": "46302536-9485-4aba-b990-18d86bbdc530", "type": "concept", "title": "language load analysis"}, {"id": "29eeefee-5643-4c98-ae01-9ce67e6bdd85", "type": "concept", "title": "accommodations"}, {"id": "666dac91-bd16-4648-abf6-582f7526b00a", "type": "concept", "title": "rubric criteria"}], "description": "Students learn to distinguish content understanding from English-language demands in assessment tasks."}, {"id": "b29874ec-e01c-4b4c-a73f-7f03dd7e0cd5", "type": "subtopic", "title": "Formative Assessment", "children": [{"id": "a68b9f2c-098e-49c5-95cb-eb587f2b9455", "type": "concept", "title": "exit tickets"}, {"id": "71fb1a32-f939-413a-b251-a4af50ff3683", "type": "concept", "title": "oral checks"}, {"id": "c911a2d9-40a6-44ff-95b6-f3679745f2c2", "type": "concept", "title": "student work analysis"}, {"id": "0eb7200c-5ac8-4b24-91b6-f4dd7756ae7d", "type": "concept", "title": "language-progress notes"}], "description": "The point is to use frequent evidence to adjust instruction before high-stakes judgments."}, {"id": "46365d5f-e1a2-4310-9064-43b87f713ad3", "type": "subtopic", "title": "Assessment Equity", "children": [{"id": "d5c567d0-639b-40b2-ab9c-47df96caf02f", "type": "concept", "title": "translation and interpretation"}, {"id": "491512ab-7ec4-4a9a-983e-4fba3361962f", "type": "concept", "title": "performance assessment"}, {"id": "94585650-a1b3-4401-982c-d5654f8a67b8", "type": "concept", "title": "portfolio evidence"}, {"id": "d9ad87dc-c4a9-4b82-8dfb-1771c9b3aa9f", "type": "concept", "title": "grading with language development in mind"}], "description": "Teachers examine bias, validity, and accessibility for multilingual learners."}]}, {"id": "3197f48a-633f-4703-a66c-73b73168f588", "type": "topic", "title": "Family and Community Engagement", "description": "This section treats families and communities as partners with linguistic, cultural, and experiential knowledge. Students learn communication practices that create trust and shared educational purpose.", "children": [{"id": "3249b8a2-171f-4f96-8205-f70f4f01b136", "type": "subtopic", "title": "Linguistically Accessible Communication", "children": [{"id": "be04bfd0-2423-4a8c-b7e7-ed5642f88d13", "type": "concept", "title": "interpreters"}, {"id": "7dfc706d-d43b-4c71-b1e6-3c5edfc1e4ac", "type": "concept", "title": "translated materials"}, {"id": "437dfc98-b19d-45c7-85c1-753a5a106936", "type": "concept", "title": "plain-language communication"}, {"id": "5c50bedd-5d5d-48ca-b568-4cf77fa646c1", "type": "concept", "title": "two-way communication systems"}], "description": "Students learn to make school communication understandable and respectful across languages."}, {"id": "41fd307b-f4a0-42f1-b5be-1b58667ddef5", "type": "subtopic", "title": "Funds of Knowledge", "children": [{"id": "f58df3dd-a64f-4fcb-9802-984b9914c5a6", "type": "concept", "title": "home literacy practices"}, {"id": "50c20ab2-5ad4-42b4-8aab-373506a8f884", "type": "concept", "title": "community histories"}, {"id": "f290f5e7-dfbe-4e55-9d9e-783696601601", "type": "concept", "title": "student interests"}, {"id": "2ac65041-c919-42a7-b569-ba0199b3ca00", "type": "concept", "title": "family expertise"}], "description": "The gist is to draw on family and community expertise as curriculum and relationship assets."}, {"id": "605a27ac-8831-4e34-86c4-0be16d24455e", "type": "subtopic", "title": "Partnership and Advocacy", "children": [{"id": "2d5396f6-f879-4d62-9b59-8c83cb1159bb", "type": "concept", "title": "family conferences"}, {"id": "21949535-64e5-4823-a76b-8513069b19dd", "type": "concept", "title": "program placement information"}, {"id": "5fefb0da-beab-4c8e-b7d3-dcf1ea3159f8", "type": "concept", "title": "rights and services"}, {"id": "e66f4a10-9c49-4d09-881c-c38bfb6d82b0", "type": "concept", "title": "community organizations"}], "description": "Teachers learn how to support families in navigating school systems and language-program decisions."}]}, {"id": "87ceb8af-3b1b-4cf1-b3b9-22376ac0dfa0", "type": "topic", "title": "Cultural Responsiveness with Multilingual Learners", "description": "This section asks teachers to examine culture, power, and identity in language education. Students learn to sustain learners' identities while teaching rigorous academic language and content.", "children": [{"id": "7dbcc546-3b4c-429a-9790-d1b6284d0f47", "type": "subtopic", "title": "Culturally Sustaining Pedagogy", "children": [{"id": "242819e6-0f27-4f52-873b-09fe0f3b5f46", "type": "concept", "title": "asset-based language"}, {"id": "691d04f8-28e4-4a78-946c-2ee05e73df3d", "type": "concept", "title": "student identity texts"}, {"id": "58bd7b23-6bac-4c7d-8ec4-c8a8795a3662", "type": "concept", "title": "community knowledge"}, {"id": "8239a16b-8900-412b-9c27-5e43553d0146", "type": "concept", "title": "critical consciousness"}], "description": "Students learn to see multilingualism as an asset and a resource for learning."}, {"id": "0f22256c-e2ed-4afb-a3ba-319a385e7ecc", "type": "subtopic", "title": "Bias and Language Ideology", "children": [{"id": "d7149f5d-67ab-4a0e-af76-b15fd0eff8f2", "type": "concept", "title": "standard language ideology"}, {"id": "17620941-3915-4d98-87ec-5a1a08f363d1", "type": "concept", "title": "accent bias"}, {"id": "4d376f86-79ff-4b21-a3be-e858017644d1", "type": "concept", "title": "deficit narratives"}, {"id": "1fe654fb-605d-47a5-b7ad-923610e1c489", "type": "concept", "title": "racialized language expectations"}], "description": "The point is to notice how assumptions about accents, grammar, and language status can shape expectations."}, {"id": "0809b4e6-8541-4f14-bffe-6c9671c4affa", "type": "subtopic", "title": "Classroom Belonging", "children": [{"id": "fdc0e090-9b8a-4b13-88b0-ac59d5444e8e", "type": "concept", "title": "pronouncing names"}, {"id": "2992d4fd-c4fe-4966-8320-58f1f48243de", "type": "concept", "title": "inclusive classroom libraries"}, {"id": "c7ccde49-0a10-4586-b496-1cb2a1e284da", "type": "concept", "title": "peer interaction norms"}, {"id": "a0d3ad19-6a81-462d-9aa1-e59b750d3657", "type": "concept", "title": "anti-bias responses"}], "description": "Teachers design routines that make multilingual learners full participants in academic and social life."}]}, {"id": "26bb567b-3c50-4e2b-b74f-70af70df61f8", "type": "topic", "title": "Translanguaging and Bilingual Pedagogies", "description": "This section frames students' full linguistic repertoires as resources for sensemaking, identity, and academic learning. Teachers learn how bilingual practices can support both content learning and English development.", "children": [{"id": "3d659cfb-5ed5-4e09-b573-fea70b7c4856", "type": "subtopic", "title": "Translanguaging Theory", "children": [{"id": "d2b7a672-61c1-44ee-a921-8af0fd59250f", "type": "concept", "title": "dynamic bilingualism"}, {"id": "4b5fd92a-6c8c-41f3-85ac-04cbcfefd0d4", "type": "concept", "title": "language practices versus named languages"}, {"id": "ca8346d3-5d7f-4191-8c5e-9d33c9736a4f", "type": "concept", "title": "identity and agency"}, {"id": "376d59ba-b466-4fa6-8fb5-f7829eff1d60", "type": "concept", "title": "strategic language use"}], "description": "Students learn why multilingual learners naturally draw on integrated language repertoires."}, {"id": "cde98f2a-a5b8-4fc4-a45e-e0f42ff5e337", "type": "subtopic", "title": "Classroom Translanguaging Routines", "children": [{"id": "573fb9b5-d952-4836-bb1e-ef54c707f780", "type": "concept", "title": "bilingual brainstorming"}, {"id": "88646a12-a214-45fd-b24f-6649f69424eb", "type": "concept", "title": "same-language peer discussion"}, {"id": "baaebd38-a78f-4d3f-81de-98f40dd1c6bd", "type": "concept", "title": "multilingual annotations"}, {"id": "93a8ee9c-6acd-4851-b48c-80e2336b2cfe", "type": "concept", "title": "dual-language products"}], "description": "The gist is to design purposeful moments where multiple languages support learning."}, {"id": "c08b411e-dc89-46a6-ae37-b4d4b1d39ddb", "type": "subtopic", "title": "Balancing English Development and Home Languages", "children": [{"id": "f1c1c2f0-434d-4313-93f6-0a399ff9c064", "type": "concept", "title": "additive bilingualism"}, {"id": "8a4813d6-8502-4303-8d5e-8aab41fe0fab", "type": "concept", "title": "heritage language maintenance"}, {"id": "72391e0d-8979-4bb1-b80b-a6abd6c837b3", "type": "concept", "title": "family language practices"}, {"id": "7d4362b5-b909-4f46-acc6-7a1969af30e4", "type": "concept", "title": "academic transfer"}], "description": "Teachers learn to support English growth without subtracting students' home languages."}]}, {"id": "3dd68416-4d9f-4ade-86aa-4f2e9823c442", "type": "topic", "title": "Academic Language and Disciplinary Literacy", "description": "This added section strengthens the course by focusing on the language of school subjects. Students learn how mathematics, science, social studies, and language arts each require specific ways of reading, writing, speaking, and reasoning.", "children": [{"id": "ad171935-a504-4d27-97c7-bc76c35e2327", "type": "subtopic", "title": "Academic Language Functions", "children": [{"id": "688ed7c4-16c5-4497-bf81-4c8ed324c538", "type": "concept", "title": "explain"}, {"id": "e02d0e91-d965-4805-8346-79cbddf203cf", "type": "concept", "title": "argue"}, {"id": "ccaecb04-d0f5-4ae9-a118-d51101d0f3e6", "type": "concept", "title": "compare"}, {"id": "7dd03596-7bd6-416b-a7d5-65193c6186ea", "type": "concept", "title": "justify"}, {"id": "50d28218-b07b-4fd5-9bfb-1b05cf4668eb", "type": "concept", "title": "describe cause and effect"}], "description": "Students learn the recurring purposes language serves in rigorous classroom tasks."}, {"id": "74dec458-9f87-48e9-9907-f0d0acb052fa", "type": "subtopic", "title": "Disciplinary Language Demands", "children": [{"id": "fb091b14-b80d-45b1-9404-1f833ca75fe5", "type": "concept", "title": "science explanations"}, {"id": "1463b630-5329-4e7d-85e9-51ec63575d21", "type": "concept", "title": "mathematical reasoning"}, {"id": "1b53169a-d97c-4ab5-82d0-f160dc3881d8", "type": "concept", "title": "historical argument"}, {"id": "1c26d6b6-bc88-4bae-9df3-6acba6c28705", "type": "concept", "title": "literary interpretation"}], "description": "The point is to identify how each subject uses specialized vocabulary, text structures, and evidence."}, {"id": "28588fce-9ee9-47a1-95cf-5836e3bf5fb4", "type": "subtopic", "title": "Language Objectives Across Content Areas", "children": [{"id": "5335d7b3-6770-4183-ba6b-d6ccd6df0938", "type": "concept", "title": "function"}, {"id": "5d81f000-ada6-47b5-9243-bbb2f61a5be7", "type": "concept", "title": "form"}, {"id": "a50c4aa3-1e8c-494f-add8-e53963232396", "type": "concept", "title": "vocabulary"}, {"id": "477e2d80-60a0-4f6d-85b1-75a1f313ce48", "type": "concept", "title": "discourse routines"}], "description": "Teachers learn to write and teach objectives that make language demands visible."}]}, {"id": "6652625b-e418-44d4-8ea3-b6331eb34e48", "type": "topic", "title": "Literacy for Multilingual Learners", "description": "This added section integrates TESOL methods with literacy development. Students learn how oral language, vocabulary, phonology, morphology, background knowledge, and reading comprehension interact for multilingual learners.", "children": [{"id": "2aa3c7cb-decf-4d19-9a46-9b342d682550", "type": "subtopic", "title": "Oral Language and Vocabulary", "children": [{"id": "950e5036-2d22-428f-847f-5dc17e6a994e", "type": "concept", "title": "semantic networks"}, {"id": "e9c806d7-270d-4749-9b99-06bd48eb1458", "type": "concept", "title": "morphology"}, {"id": "474ae7ff-c47a-461a-b65c-81100f443755", "type": "concept", "title": "cognates"}, {"id": "124d3d56-743b-4c9b-98b8-655c4aea00c1", "type": "concept", "title": "multiple-meaning words"}], "description": "Students learn why rich oral language and word knowledge are central to literacy growth."}, {"id": "b3c2bbc7-0499-4f42-b376-48a19992d33d", "type": "subtopic", "title": "Reading and Writing Development", "children": [{"id": "92222da3-29bb-4000-a15a-a3587d53d2c3", "type": "concept", "title": "phonological awareness across languages"}, {"id": "1dd10907-b022-49af-899a-b6169e81b8c2", "type": "concept", "title": "decoding and spelling"}, {"id": "3f616805-74d7-456d-87ee-12bc88b5dae8", "type": "concept", "title": "reading comprehension"}, {"id": "579264a2-22ae-4f1e-80f5-d4b9704e570d", "type": "concept", "title": "genre-based writing"}], "description": "The gist is to align evidence-based literacy instruction with multilingual learners' language assets."}, {"id": "294f3173-1d19-440a-bc03-647a9653066c", "type": "subtopic", "title": "Biliteracy and Cross-Language Transfer", "children": [{"id": "4e8117cf-b9cb-4b80-b4c3-341647aadd68", "type": "concept", "title": "transferable skills"}, {"id": "e1086dac-c62b-41a5-90d9-818b2808de66", "type": "concept", "title": "contrastive analysis"}, {"id": "628b49cc-ad17-4b47-87dc-ac7f4ebe35be", "type": "concept", "title": "cognate strategy"}, {"id": "b141f3f7-fd3b-4f5d-9f9e-e3ddf7029624", "type": "concept", "title": "multilingual text sets"}], "description": "Teachers learn how first-language literacy can support English literacy."}]}, {"id": "67902a35-861c-45bf-ba27-0c3996073ffe", "type": "topic", "title": "Newcomers, SIFE, and Trauma-Informed Supports", "description": "This added section prepares teachers for students whose schooling, migration, or trauma histories require coordinated academic and social-emotional support. The aim is responsive acceleration, not remediation rooted in deficit thinking.", "children": [{"id": "54887c39-53a6-44d6-b113-1fe40c9b893c", "type": "subtopic", "title": "Newcomer Orientation", "children": [{"id": "cb2581e1-db04-4025-9b77-9f935f8704c5", "type": "concept", "title": "welcoming routines"}, {"id": "a740b00a-4008-427e-af0b-6f713da14525", "type": "concept", "title": "survival language"}, {"id": "5b557c5d-5918-4926-a469-f664357a4c17", "type": "concept", "title": "buddy systems"}, {"id": "1a9be369-eca3-418f-9ecf-3e9d9a0f21e3", "type": "concept", "title": "visual schedules"}], "description": "Students learn routines that help newly arrived learners navigate school culture and classroom expectations."}, {"id": "eba09e68-c958-4d8e-9c88-ced358aae2b9", "type": "subtopic", "title": "Students with Interrupted Formal Education", "children": [{"id": "7813cf4b-2591-4f28-b4d6-15fd072c408f", "type": "concept", "title": "literacy and numeracy screening"}, {"id": "9a689bd0-fe14-45aa-9f37-8a54cb61b59b", "type": "concept", "title": "accelerated foundational support"}, {"id": "07008d34-c331-41ed-a48d-65441471fa86", "type": "concept", "title": "age-appropriate materials"}, {"id": "8a984cc5-6abe-43d5-8ffa-933630dfd5b2", "type": "concept", "title": "flexible grouping"}], "description": "The point is to address gaps in schooling while honoring students' intelligence and life experience."}, {"id": "4ac4c959-eb26-4006-841a-8267ebcbf436", "type": "subtopic", "title": "Trauma-Informed and Asset-Based Support", "children": [{"id": "fd733203-c249-4d45-9316-b3ef6b803b12", "type": "concept", "title": "predictable routines"}, {"id": "cf092020-d3ef-4edf-9ce5-fa7c486058b1", "type": "concept", "title": "relationship-building"}, {"id": "64f7cc06-1929-4604-b395-075eccb5e2df", "type": "concept", "title": "choice and agency"}, {"id": "733b27bb-f804-44c6-9ab7-b41e67b74c2a", "type": "concept", "title": "referral and support teams"}], "description": "Teachers learn to support safety, belonging, and learning without making assumptions about students' experiences."}]}, {"id": "a3ba1c5d-9418-4665-bca9-d4e192a25bd6", "type": "topic", "title": "Language Policy, Legal Context, and Program Models", "description": "This added section gives educators the policy literacy needed to collaborate with leaders and advocate for multilingual learners. Students learn how program models and legal rights shape daily instruction.", "children": [{"id": "ae82edfc-ae83-4662-9469-b9befc1cc99e", "type": "subtopic", "title": "Legal Foundations", "children": [{"id": "76a2a96a-ab93-46c8-836d-3f26f0729798", "type": "concept", "title": "Lau v. Nichols"}, {"id": "8eefca61-7804-4d6b-8761-161ed33a4f3c", "type": "concept", "title": "equal access"}, {"id": "772ad42a-3554-4fc9-b148-f82e1474f4f3", "type": "concept", "title": "identification and placement"}, {"id": "13dc3d20-c399-4fe2-9c5a-4134f0b865ca", "type": "concept", "title": "monitoring and exit"}], "description": "Students learn the basic civil-rights and educational obligations schools have toward English learners."}, {"id": "e7cdf164-86d4-485b-8781-6b0bb82ac98c", "type": "subtopic", "title": "Program Models", "children": [{"id": "eb4be66b-960c-40a9-bb03-a9d96bdfaf7d", "type": "concept", "title": "ESL pull-out and push-in"}, {"id": "7d53403f-09ba-4735-8a47-6df648857e73", "type": "concept", "title": "sheltered content"}, {"id": "5e62a857-1d0c-4ddf-95e5-deb14287efb4", "type": "concept", "title": "dual language"}, {"id": "31bbc3fb-25eb-44b6-aba9-1bee8deb8ff0", "type": "concept", "title": "newcomer programs"}], "description": "The gist is to understand how different models organize language and content instruction."}, {"id": "2e9ed4ab-abdb-4200-ab4d-69443e9b2200", "type": "subtopic", "title": "Collaboration and Advocacy", "children": [{"id": "7f8844d8-8deb-4a58-ae73-c0e501fb4a51", "type": "concept", "title": "general educator and ESL teacher collaboration"}, {"id": "9ef37f9e-fba2-4578-96a2-17c9bef89f55", "type": "concept", "title": "administrator communication"}, {"id": "299f965f-22fd-4b18-8df5-db07f7f7f75e", "type": "concept", "title": "family rights"}, {"id": "781a02ff-71a3-4fec-94ee-e825fcbf3d68", "type": "concept", "title": "equitable access to advanced coursework"}], "description": "Teachers learn to work across roles to support coherent services."}]}, {"id": "d430bcaf-91ce-474e-b12a-bebe763f500f", "type": "topic", "title": "TESOL Lesson Design and Clinical Practice", "description": "This added capstone-style section turns the course into practice. Students design, teach, observe, revise, and defend lessons that integrate content objectives, language objectives, scaffolds, assessment, and multilingual assets.", "children": [{"id": "b538ed09-4eac-4120-bca5-8d71c7681109", "type": "subtopic", "title": "Lesson Planning Studio", "children": [{"id": "64bf6c58-a3f5-4d80-bbca-75ac5176861c", "type": "concept", "title": "content objectives"}, {"id": "7bd5f423-0b3e-4744-9103-dfe44f6f916f", "type": "concept", "title": "language objectives"}, {"id": "21c56046-ce1f-43e8-bf45-c6b72f71c3df", "type": "concept", "title": "scaffolds"}, {"id": "de16c7ca-af86-4370-8d38-c21c2c69e001", "type": "concept", "title": "assessment evidence"}], "description": "Students build TESOL-informed lessons that are rigorous, accessible, and standards-aligned."}, {"id": "50044df5-1022-4001-8ef0-2279fea1f269", "type": "subtopic", "title": "Microteaching and Observation", "children": [{"id": "d1283a70-c3d3-437b-9c6a-30735ae81fdb", "type": "concept", "title": "teacher talk"}, {"id": "b9289a2d-a379-4021-9291-68396abe7544", "type": "concept", "title": "student interaction"}, {"id": "a1a72615-e1e4-4f28-9df0-2003d7a45801", "type": "concept", "title": "comprehension checks"}, {"id": "fc6612dd-b604-484d-a08b-273e226c1a56", "type": "concept", "title": "language-output opportunities"}], "description": "The point is to practice strategies and receive focused feedback before full implementation."}, {"id": "57d8a840-fd58-4db3-b940-d3b332f157ed", "type": "subtopic", "title": "Reflection and Revision", "children": [{"id": "e83e2a61-304c-4e6f-a32d-936e6c62e7f7", "type": "concept", "title": "student work analysis"}, {"id": "ff92a612-e4f5-4190-b89c-b0b489982534", "type": "concept", "title": "language-growth evidence"}, {"id": "1faf43df-f960-4f12-9e50-b60dbc8a03f6", "type": "concept", "title": "lesson debrief"}, {"id": "d7dff0fb-f460-4edc-b258-690fff33c23e", "type": "concept", "title": "next-step planning"}], "description": "Teachers learn to use student evidence and peer feedback to improve instruction."}]}], "dbBacked": true}$tesljson$::jsonb,
