ull implementation."}, {"id": "57d8a840-fd58-4db3-b940-d3b332f157ed", "type": "subtopic", "title": "Reflection and Revision", "children": [{"id": "e83e2a61-304c-4e6f-a32d-936e6c62e7f7", "type": "concept", "title": "student work analysis"}, {"id": "ff92a612-e4f5-4190-b89c-b0b489982534", "type": "concept", "title": "language-growth evidence"}, {"id": "1faf43df-f960-4f12-9e50-b60dbc8a03f6", "type": "concept", "title": "lesson debrief"}, {"id": "d7dff0fb-f460-4edc-b258-690fff33c23e", "type": "concept", "title": "next-step planning"}], "description": "Teachers learn to use student evidence and peer feedback to improve instruction."}]}], "dbBacked": true}$tesljson$::jsonb,
